describe('Payment Flow - Invalid Card Number', () => {
  beforeEach(() => {
    cy.visit('/payment');
    cy.get('[data-testid="card-number-input"]').should('be.visible');
  });

  it('should display error message when entering invalid card number', () => {
    cy.get('[data-testid="card-number-input"]').type('1234567890123456');
    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid card number');
  });

  it('should display error for card number with invalid length', () => {
    cy.get('[data-testid="card-number-input"]').type('123');
    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid card number');
  });

  it('should display error for card number with special characters', () => {
    cy.get('[data-testid="card-number-input"]').type('1234-5678-9012-34@5');
    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid card number');
  });

  it('should clear error message when valid card number is entered', () => {
    cy.get('[data-testid="card-number-input"]').type('1234567890123456');
    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="card-number-input"]').clear().type('4532015112830366');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
